arguments.file_text:
@page "/chat"
@namespace sv_767782cb4a1f4435ae18e9d96553974b.Components.Pages
@rendermode InteractiveServer
@using sv_767782cb4a1f4435ae18e9d96553974b.Components.Chat
@using sv_767782cb4a1f4435ae18e9d96553974b.Models
@using sv_767782cb4a1f4435ae18e9d96553974b.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_isThreadOpen ? "with-thread" : "")">
        <MessageArea Channel="_activeChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     IsLoadingOlder="_isLoadingOlder"
                     OnLoadOlder="LoadOlderMessages"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnAddReaction="AddReaction" />
    </div>

    @if (_isThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     IsLoading="_isLoadingThread"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];

    private int _activeChannelId;
    private Channel? _activeChannel;

    private bool _isThreadOpen;
    private int _threadRootMessageId;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];
    private bool _isLoadingThread;
    private bool _isLoadingOlder;

    private const int PageSize = 30;
    private int _currentSkip;

    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<Chat>? _dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Chat.razor.js");
            await _jsModule.InvokeVoidAsync("initScrollDetection", ".message-list", _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_isLoadingOlder) return;
        await LoadOlderMessages();
        StateHasChanged();
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _currentSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _currentSkip = _messages.Count;

        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (_activeChannel is null) return;
        _isLoadingOlder = true;

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _currentSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _currentSkip += older.Count;
            BuildThreadSummaries();
        }

        _isLoadingOlder = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(msg);
        _currentSkip++;
    }

    private async Task OpenThread(int messageId)
    {
        _isThreadOpen = true;
        _isLoadingThread = true;
        _threadRootMessageId = messageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _isLoadingThread = false;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadReplies = [];
        _threadRootMessage = null;
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessageId);
        _threadReplies.Add(reply);

        // Update thread summary count
        var idx = _threadSummaries.FindIndex(t => t.RootMessageId == _threadRootMessageId);
        if (idx >= 0)
        {
            var old = _threadSummaries[idx];
            _threadSummaries[idx] = old with { ReplyCount = old.ReplyCount + 1, LastReplyAt = DateTime.UtcNow };
        }
        else
        {
            _threadSummaries.Add(new ThreadSummary(_threadRootMessageId, 1, DateTime.UtcNow));
        }
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update
        var msgIdx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (msgIdx >= 0)
        {
            var msg = _messages[msgIdx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("me"))
                {
                    reactions[existing] = r with { Users = [..r.Users, "me"] };
                }
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["me"]));
            }
            _messages[msgIdx] = msg with { Reactions = reactions };
        }
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try { await _jsModule.InvokeVoidAsync("dispose"); } catch { }
            await _jsModule.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let observer = null;
let scrollEl = null;

export function initScrollDetection(selector, dotNetRef) {
    scrollEl = document.querySelector(selector);
    if (!scrollEl) return;

    scrollEl.addEventListener('scroll', () => {
        if (scrollEl.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

export function dispose() {
    scrollEl = null;
}

/* ===== Chat Layout ===== */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d1c1d;
}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

::deep .sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #522653;
}

::deep .sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 6px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.1s;
    position: relative;
}

::deep .channel-item:hover {
    background: #4a154b;
}

::deep .channel-item.active {
    background: #1264a3;
    color: #fff;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-name .hash {
    opacity: 0.6;
    margin-right: 2px;
}

::deep .channel-desc {
    width: 100%;
    font-size: 0.75rem;
    opacity: 0.7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #e01e5a;
    color: #fff;
    border-radius: 10px;
    padding: 1px 7px;
    font-size: 0.75rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* ===== Main Message Area ===== */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

::deep .message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
    background: #fff;
}

::deep .channel-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e1e1e1;
}

::deep .channel-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
}

::deep .channel-header .hash {
    opacity: 0.4;
    margin-right: 2px;
}

::deep .channel-header .channel-description {
    margin: 2px 0 0;
    font-size: 0.85rem;
    color: #616061;
}

::deep .no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

/* ===== Message List ===== */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 20px;
}

::deep .loading-older {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

/* ===== Message Item ===== */
::deep .message-item {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-item:hover {
    background: #f8f8f8;
}

::deep .message-item.highlighted {
    background: #fff8e1;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 700;
    font-size: 0.95rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #999;
}

::deep .message-content {
    font-size: 0.95rem;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

/* ===== Reactions ===== */
::deep .reaction-bar {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: #f0f0f0;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #e0e8ff;
    border-color: #99b3ff;
}

::deep .reaction-count {
    font-weight: 600;
    color: #555;
}

/* ===== Thread Link ===== */
::deep .thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 4px 0 0;
